svg.script:
(function () {
  var all = document.getElementsByTagName(`script`);
  var root = (document.currentScript || all[all.length - 1]).ownerSVGElement;
  var hit = root.querySelector(`.hit`);
  function toggle() {
    var on = root.getAttribute(`data-state`) === `off`;
    root.setAttribute(`data-state`, on ? `on` : `off`);
    hit.setAttribute(`aria-checked`, on ? `true` : `false`);
  }
  hit.addEventListener(`click`, toggle);
  hit.addEventListener(`keydown`, function (e) {
    if (e.key === ` ` || e.key === `Enter`) {
      e.preventDefault();
      if (!e.repeat) toggle();
    }
  });
})();
